import {roomScene,researchText} from './lab-scene.js';
import {researchGrade} from './engine.js';
const labels={study:'문헌 공부',coursework:'교과목 공부',experiment:'연구',analysis:'데이터 분석',paper:'논문 쓰기',conference:'학회에서 배우기',free:'자율 시간',travel:'여행·새로운 경험',rest:'휴식',language:'읽고 말하기',industry:'산학과제 수행 · RA',video:'과학 콘텐츠',teach:'수업보조 · TA',unfinished:'계획 다시 살피기'};
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function weeklyScene(state,result,index){
 const id=result.actual,scientific=Number.isFinite(result.successRate),success=scientific?result.successRate>=.4:result.performed;
 const status=result.proposed==='free'&&result.performed?({coursework:'자율 시간에 시험 공부를 했어요',study:'자율 시간에 스스로 공부했어요',rest:'자율 시간에 충분히 쉬었어요',travel:'자율 시간에 여행을 다녀왔어요'})[result.autonomous]:!result.performed?'계획을 다 마치지는 못했어요':result.outcome==='presentation_failed'?'발표를 충분히 준비하지 못했어요':result.outcome==='inconclusive'?'이번 시도에서는 결과를 얻지 못했어요':id==='rest'?'충분히 쉬었어요':id==='conference'?(result.outcome==='presented'?'연구를 발표했어요':'현장에서 배웠어요'):'이번 주 계획을 수행했어요';
 const progress=result.progress>0?`연구 진척 +${result.progress.toFixed(1)}`:scientific?'연구 진척 0 · 시도도 기록에 남습니다.':id==='rest'?'다음 주를 위한 여유':'배운 것을 기록했습니다.';
 return `<div class="weekly-stage ${success?'week-success':'week-trying'} task-${id}" aria-label="${index+1}주차 수행 결과"><div class="week-scene-header"><span>${index+1}주차 / ${state.lastReport?.results.length??state.plan.length}</span><strong>${id==='experiment'&&state.professorProfile.labMode==='dry'?'계산·모델링':labels[id]||labels[result.proposed]}</strong></div>${roomScene(state,result,index)}<div class="week-outcome"><strong>${escape(scientific?`${researchGrade(result.successRate)} · 수행률 ${Math.round(result.successRate*100)}%`:status)}</strong><p>${escape(progress)}</p><ol class="week-dots" aria-label="주별 진행">${Array.from({length:state.lastReport?.results.length??state.plan.length},(_,i)=>`<li class="${i<index?'done':i===index?'current':''}">${i+1}주</li>`).join('')}</ol></div></div>`;
}
